"""Tests for rolling, EWMA, GARCH, and GJR-GARCH volatility models."""

import numpy as np
import pandas as pd
import pytest

from riskkit.config import VolatilitySpec
from riskkit.volatility import analysis, ewma, garch, rolling
from riskkit.volatility.base import horizon_vol


def simulated_garch(n=3000, omega=2e-6, alpha=0.08, beta=0.9, seed=1):
    """Returns generated by a known GARCH(1,1) process, to check the fit recovers it."""
    rng = np.random.default_rng(seed)
    var, out = omega / (1 - alpha - beta), np.empty(n)
    for t in range(n):
        out[t] = np.sqrt(var) * rng.standard_normal()
        var = omega + alpha * out[t] ** 2 + beta * var
    return pd.Series(out, index=pd.bdate_range("2010-01-01", periods=n))


def test_ewma_recursion_by_hand():
    """With lambda 0.5 and seed variance v0: v1 = 0.5 v0 + 0.5 r0^2."""
    r = np.array([0.02, -0.01, 0.0] + [0.01] * 30)
    v = ewma.ewma_variance(r, 0.5, seed_days=30)
    assert v[1] == pytest.approx(0.5 * v[0] + 0.5 * 0.02**2)
    assert len(v) == len(r) + 1


def test_rolling_sigma_uses_only_past_days():
    """No look-ahead: a huge return on day t must not change sigma on day t."""
    r = pd.Series(np.full(100, 0.01) * np.tile([1, -1], 50), index=pd.bdate_range("2024-01-01", periods=100))
    shocked = r.copy()
    shocked.iloc[80] = 0.5
    a = rolling.RollingVol(20).fit(r).sigma
    b = rolling.RollingVol(20).fit(shocked).sigma
    assert a.iloc[: 80 - 20 + 1].equals(b.iloc[: 80 - 20 + 1]) and a.loc[r.index[80]] == b.loc[r.index[80]]
    assert b.loc[r.index[81]] > a.loc[r.index[81]]


def test_garch_recovers_known_parameters():
    """On data made by a GARCH with persistence 0.98, the fit lands close to it."""
    fit = garch.GarchVol().fit(simulated_garch())
    assert fit.params["persistence"] == pytest.approx(0.98, abs=0.02)
    assert fit.params["gamma"] == 0.0


def test_gjr_news_impact_is_asymmetric():
    """With gamma > 0, a -3% day raises tomorrow's volatility more than a +3% day."""
    p = {"omega": 1e-6, "alpha": 0.02, "gamma": 0.15, "beta": 0.85}
    down, up = garch.news_impact(p, np.array([-0.03, 0.03]))
    assert down > up


def test_garch_forecast_drifts_to_long_run():
    """After a calm spell the forecast rises towards the long-run level; horizon vol adds variances."""
    r = simulated_garch()
    r.iloc[-60:] = r.iloc[-60:] * 0.2
    fit = garch.GarchVol().fit(r, horizon=50)
    assert fit.forecast[-1] > fit.forecast[0]
    assert horizon_vol(fit, 2) == pytest.approx(np.sqrt(fit.forecast[0] ** 2 + fit.forecast[1] ** 2))


def test_all_models_share_one_interface():
    """Every model returns a VolFit with a sigma series and a forecast of the requested length."""
    fits = analysis.fit_all(simulated_garch(800), VolatilitySpec(horizon=7))
    assert set(fits) == {"Rolling 63d", "EWMA", "GARCH", "GJR-GARCH"}
    for f in fits.values():
        assert len(f.forecast) == 7 and (f.sigma > 0).all() and f.next_day > 0


def test_regimes_and_scaling():
    """Regimes split days into thirds; scaling makes a calm-period return bigger when today is stormy."""
    r = simulated_garch(600)
    fit = ewma.EWMAVol().fit(r)
    labels = analysis.volatility_regimes(fit.sigma)
    assert labels.value_counts().min() >= len(labels) // 3 - 2
    scaled = analysis.scale_to_today(r, fit)
    d = fit.sigma.idxmin()
    assert abs(scaled[d]) >= abs(r[d]) * 0.999
